import{_ as t,o as r,c as s,ag as n}from"./chunks/framework.C15dTZqp.js";const m=JSON.parse(`{"title":"L'IA dans la discovery produit","description":"","frontmatter":{},"headers":[],"relativePath":"handout-04-discovery-produit.md","filePath":"handout-04-discovery-produit.md","handout":{"fichier":"handout-04-discovery-produit.md","markdown":"# Handout — L'IA dans la discovery produit\\n\\n**Speed training IA · Zenika · fiche module 4**\\n\\nAller plus vite vers la preuve, sans sauter la preuve : où l'IA accélère le travail produit, et ce qui reste humain.\\n\\n## Mode projet ou mode produit ?\\n\\n| Mode projet                                              | Mode produit                                                       |\\n| -------------------------------------------------------- | ------------------------------------------------------------------ |\\n| Un comité décide de tout refaire.                        | On mesure 38 % d'abandons au paiement mobile.                      |\\n| 9 mois de développement : on livre le plan.              | 6 interviews et un prototype en 2 semaines : on teste l'hypothèse. |\\n| Au lancement, les abandons ne baissent pas.              | Le test montre que le paiement en 1 clic marche.                   |\\n| On découvre trop tard que le problème était le paiement. | On construit ce qui a fait ses preuves.                            |\\n\\nL'IA rend le **mode produit** beaucoup moins cher : interviewer, synthétiser, prototyper prend des heures, et non plus des mois.\\n\\n## Interroger sur des faits, pas des opinions\\n\\nLes clients prédisent mal leur propre comportement. Posez des questions sur ce qu'ils ont **fait**, pas sur ce qu'ils **pensent** qu'ils feraient.\\n\\n| À éviter                                                                      | À la place                                                                      |\\n| ----------------------------------------------------------------------------- | ------------------------------------------------------------------------------- |\\n| **Opinion** : « Quelles fonctionnalités voudriez-vous ? »                     | **Fait vécu** : « Racontez-moi la dernière fois que vous avez réservé. »        |\\n| **Hypothèse** : « Utiliseriez-vous ceci si on le construisait ? »             | **Chronologie** : « Reprenez depuis le début : que faisiez-vous juste avant ? » |\\n| **Question orientée** : « Ce n'est pas frustrant quand le paiement échoue ? » | **Creuser l'histoire** : « Pourquoi avez-vous fait comme ça ? »                 |\\n\\n## Du terrain au PRD\\n\\n| Étape              | Ce que c'est                                               | L'IA aide à                                | Reste humain                   |\\n| ------------------ | ---------------------------------------------------------- | ------------------------------------------ | ------------------------------ |\\n| **Interviews**     | 5 à 8 utilisateurs racontent des situations réelles        | transcrire, regrouper les thèmes           | parler à de vrais clients      |\\n| **Experience map** | le parcours de bout en bout : étapes, ressentis, irritants | structurer la carte, repérer les irritants | choisir l'irritant à traiter   |\\n| **PRD**            | une page : quoi construire, pourquoi, comment mesurer      | rédiger un premier jet                     | arbitrer objectif et périmètre |\\n| **Prototype**      | une maquette cliquable pour tester avant de développer     | générer une maquette en quelques heures    | observer de vrais utilisateurs |\\n\\n## Le PRD, c'est quoi ?\\n\\nLe **PRD** (_Product Requirements Document_) est le contrat de l'équipe produit : **une page**, pas un cahier des charges. Il est écrit par le PO ou le PM avec le designer et le tech lead, après la discovery et avant de construire. Il dit **quoi** construire, **pourquoi**, et comment on mesure le succès ; le _comment_ technique reste à l'équipe.\\n\\nModèle en 6 rubriques, avec l'exemple du parcours de réservation :\\n\\n| Rubrique              | Exemple                                                                                      |\\n| --------------------- | -------------------------------------------------------------------------------------------- |\\n| **Problème**          | 38 % des réservations mobiles abandonnées au paiement.                                       |\\n| **Objectif**          | Passer de 38 % à 30 % d'abandons en 3 mois.                                                  |\\n| **User story**        | En tant que client mobile, je veux payer en 1 clic pour finir ma réservation sans ressaisie. |\\n| **Périmètre**         | Paiement mobile. Hors périmètre : desktop.                                                   |\\n| **Hypothèse**         | La ressaisie de la carte bloque.                                                             |\\n| **Critère de succès** | Moins de 30 % d'abandons, 4 semaines de suite.                                               |\\n\\nL'IA rédige un premier jet à partir des interviews ; l'équipe **arbitre** le problème, l'objectif et le périmètre. Relisez toujours ce qu'elle a inventé : un chiffre qui n'est pas dans vos sources doit être marqué « à mesurer ».\\n\\n## Prototyper : lo-fi d'abord\\n\\nLa **fidélité** (« fi ») mesure à quel point la maquette ressemble au produit final.\\n\\n| Niveau     | À quoi ça ressemble                               | Temps                                      | Sert à                       |\\n| ---------- | ------------------------------------------------- | ------------------------------------------ | ---------------------------- |\\n| **Lo-fi**  | un croquis, des boîtes grises                     | quelques minutes                           | explorer, aligner l'équipe   |\\n| **Mid-fi** | la structure et les vrais libellés, sans couleurs | quelques heures                            | valider le parcours          |\\n| **Hi-fi**  | presque le vrai produit, cliquable                | quelques jours (quelques heures avec l'IA) | tester avec des utilisateurs |\\n\\nTrop beau trop tôt = changements chers trop tard. Avec l'IA, demandez explicitement une maquette « en niveaux de gris, sans couleurs » pour rester lo-fi au début.\\n\\n## Un prototype n'est pas un produit\\n\\n« Il est génial ce prototype… on le met en prod la semaine prochaine ? » Non :\\n\\n| Prototype                             | Produit                                              |\\n| ------------------------------------- | ---------------------------------------------------- |\\n| Données fictives, sans droits d'accès | Données réelles : qui voit quoi, pas de fuite        |\\n| Une démo, une personne                | Des milliers d'utilisateurs, retour arrière possible |\\n| En cas d'erreur, on recharge la page  | Accès contrôlés, erreurs détectées et suivies        |\\n| On régénère                           | Une équipe le fait évoluer dans la durée             |\\n\\nAvant toute démo, annoncez que c'est une **maquette**.\\n\\n## Tester, apprendre, recommencer\\n\\nLe **user testing** consiste à observer de vrais utilisateurs, pas à leur demander ce qu'ils veulent :\\n\\n- **Avant** : une question à laquelle répondre, 2 à 4 tâches réalistes, les bonnes personnes.\\n- **Pendant** : observer sans aider ; noter hésitations, clics ratés, abandons.\\n- **Après** : synthétiser à plusieurs, corriger, retester.\\n\\nC'est une boucle : prototyper → tester → apprendre → nouvelle question. Exemple : le paiement en 1 clic marche… sauf avec une carte d'entreprise. C'est la **continuous discovery** : la discovery ne s'arrête pas au lancement.\\n\\n## À retenir\\n\\n1. Interrogez sur des **faits vécus**, jamais sur des intentions.\\n2. Le PRD tient en **une page** : problème, objectif mesurable, périmètre, critère de succès.\\n3. Prototypez **lo-fi** d'abord, et testez avec de vrais utilisateurs.\\n4. Utilisez l'IA pour aller plus vite vers la preuve, pas pour sauter la preuve.\\n\\n**Mots-clés** : product discovery, MVP, user interview, experience map, PRD, prototype lo-fi / hi-fi, user testing, continuous discovery — voir le glossaire.\\n"}}`),o={name:"handout-04-discovery-produit.md"};function i(a,e,u,d,l,p){return r(),s("div",null,[...e[0]||(e[0]=[n('<p class="zh-type">fiche module 4</p><h1 id="handout-l-ia-dans-la-discovery-produit" tabindex="-1">L’IA dans la discovery produit <a class="header-anchor" href="#handout-l-ia-dans-la-discovery-produit" aria-label="Permalink to &quot;Handout — L&#39;IA dans la discovery produit&quot;">​</a></h1><p>Aller plus vite vers la preuve, sans sauter la preuve : où l’IA accélère le travail produit, et ce qui reste humain.</p><h2 id="mode-projet-ou-mode-produit" tabindex="-1">Mode projet ou mode produit ? <a class="header-anchor" href="#mode-projet-ou-mode-produit" aria-label="Permalink to &quot;Mode projet ou mode produit ?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode projet</th><th>Mode produit</th></tr></thead><tbody><tr><td>Un comité décide de tout refaire.</td><td>On mesure 38 % d’abandons au paiement mobile.</td></tr><tr><td>9 mois de développement : on livre le plan.</td><td>6 interviews et un prototype en 2 semaines : on teste l’hypothèse.</td></tr><tr><td>Au lancement, les abandons ne baissent pas.</td><td>Le test montre que le paiement en 1 clic marche.</td></tr><tr><td>On découvre trop tard que le problème était le paiement.</td><td>On construit ce qui a fait ses preuves.</td></tr></tbody></table><p>L’IA rend le <strong>mode produit</strong> beaucoup moins cher : interviewer, synthétiser, prototyper prend des heures, et non plus des mois.</p><h2 id="interroger-sur-des-faits-pas-des-opinions" tabindex="-1">Interroger sur des faits, pas des opinions <a class="header-anchor" href="#interroger-sur-des-faits-pas-des-opinions" aria-label="Permalink to &quot;Interroger sur des faits, pas des opinions&quot;">​</a></h2><p>Les clients prédisent mal leur propre comportement. Posez des questions sur ce qu’ils ont <strong>fait</strong>, pas sur ce qu’ils <strong>pensent</strong> qu’ils feraient.</p><table tabindex="0"><thead><tr><th>À éviter</th><th>À la place</th></tr></thead><tbody><tr><td><strong>Opinion</strong> : « Quelles fonctionnalités voudriez-vous ? »</td><td><strong>Fait vécu</strong> : « Racontez-moi la dernière fois que vous avez réservé. »</td></tr><tr><td><strong>Hypothèse</strong> : « Utiliseriez-vous ceci si on le construisait ? »</td><td><strong>Chronologie</strong> : « Reprenez depuis le début : que faisiez-vous juste avant ? »</td></tr><tr><td><strong>Question orientée</strong> : « Ce n’est pas frustrant quand le paiement échoue ? »</td><td><strong>Creuser l’histoire</strong> : « Pourquoi avez-vous fait comme ça ? »</td></tr></tbody></table><h2 id="du-terrain-au-prd" tabindex="-1">Du terrain au PRD <a class="header-anchor" href="#du-terrain-au-prd" aria-label="Permalink to &quot;Du terrain au PRD&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Étape</th><th>Ce que c’est</th><th>L’IA aide à</th><th>Reste humain</th></tr></thead><tbody><tr><td><strong>Interviews</strong></td><td>5 à 8 utilisateurs racontent des situations réelles</td><td>transcrire, regrouper les thèmes</td><td>parler à de vrais clients</td></tr><tr><td><strong>Experience map</strong></td><td>le parcours de bout en bout : étapes, ressentis, irritants</td><td>structurer la carte, repérer les irritants</td><td>choisir l’irritant à traiter</td></tr><tr><td><strong>PRD</strong></td><td>une page : quoi construire, pourquoi, comment mesurer</td><td>rédiger un premier jet</td><td>arbitrer objectif et périmètre</td></tr><tr><td><strong>Prototype</strong></td><td>une maquette cliquable pour tester avant de développer</td><td>générer une maquette en quelques heures</td><td>observer de vrais utilisateurs</td></tr></tbody></table><h2 id="le-prd-c-est-quoi" tabindex="-1">Le PRD, c’est quoi ? <a class="header-anchor" href="#le-prd-c-est-quoi" aria-label="Permalink to &quot;Le PRD, c&#39;est quoi ?&quot;">​</a></h2><p>Le <strong>PRD</strong> (<em>Product Requirements Document</em>) est le contrat de l’équipe produit : <strong>une page</strong>, pas un cahier des charges. Il est écrit par le PO ou le PM avec le designer et le tech lead, après la discovery et avant de construire. Il dit <strong>quoi</strong> construire, <strong>pourquoi</strong>, et comment on mesure le succès ; le <em>comment</em> technique reste à l’équipe.</p><p>Modèle en 6 rubriques, avec l’exemple du parcours de réservation :</p><table tabindex="0"><thead><tr><th>Rubrique</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Problème</strong></td><td>38 % des réservations mobiles abandonnées au paiement.</td></tr><tr><td><strong>Objectif</strong></td><td>Passer de 38 % à 30 % d’abandons en 3 mois.</td></tr><tr><td><strong>User story</strong></td><td>En tant que client mobile, je veux payer en 1 clic pour finir ma réservation sans ressaisie.</td></tr><tr><td><strong>Périmètre</strong></td><td>Paiement mobile. Hors périmètre : desktop.</td></tr><tr><td><strong>Hypothèse</strong></td><td>La ressaisie de la carte bloque.</td></tr><tr><td><strong>Critère de succès</strong></td><td>Moins de 30 % d’abandons, 4 semaines de suite.</td></tr></tbody></table><p>L’IA rédige un premier jet à partir des interviews ; l’équipe <strong>arbitre</strong> le problème, l’objectif et le périmètre. Relisez toujours ce qu’elle a inventé : un chiffre qui n’est pas dans vos sources doit être marqué « à mesurer ».</p><h2 id="prototyper-lo-fi-d-abord" tabindex="-1">Prototyper : lo-fi d’abord <a class="header-anchor" href="#prototyper-lo-fi-d-abord" aria-label="Permalink to &quot;Prototyper : lo-fi d&#39;abord&quot;">​</a></h2><p>La <strong>fidélité</strong> (« fi ») mesure à quel point la maquette ressemble au produit final.</p><table tabindex="0"><thead><tr><th>Niveau</th><th>À quoi ça ressemble</th><th>Temps</th><th>Sert à</th></tr></thead><tbody><tr><td><strong>Lo-fi</strong></td><td>un croquis, des boîtes grises</td><td>quelques minutes</td><td>explorer, aligner l’équipe</td></tr><tr><td><strong>Mid-fi</strong></td><td>la structure et les vrais libellés, sans couleurs</td><td>quelques heures</td><td>valider le parcours</td></tr><tr><td><strong>Hi-fi</strong></td><td>presque le vrai produit, cliquable</td><td>quelques jours (quelques heures avec l’IA)</td><td>tester avec des utilisateurs</td></tr></tbody></table><p>Trop beau trop tôt = changements chers trop tard. Avec l’IA, demandez explicitement une maquette « en niveaux de gris, sans couleurs » pour rester lo-fi au début.</p><h2 id="un-prototype-n-est-pas-un-produit" tabindex="-1">Un prototype n’est pas un produit <a class="header-anchor" href="#un-prototype-n-est-pas-un-produit" aria-label="Permalink to &quot;Un prototype n&#39;est pas un produit&quot;">​</a></h2><p>« Il est génial ce prototype… on le met en prod la semaine prochaine ? » Non :</p><table tabindex="0"><thead><tr><th>Prototype</th><th>Produit</th></tr></thead><tbody><tr><td>Données fictives, sans droits d’accès</td><td>Données réelles : qui voit quoi, pas de fuite</td></tr><tr><td>Une démo, une personne</td><td>Des milliers d’utilisateurs, retour arrière possible</td></tr><tr><td>En cas d’erreur, on recharge la page</td><td>Accès contrôlés, erreurs détectées et suivies</td></tr><tr><td>On régénère</td><td>Une équipe le fait évoluer dans la durée</td></tr></tbody></table><p>Avant toute démo, annoncez que c’est une <strong>maquette</strong>.</p><h2 id="tester-apprendre-recommencer" tabindex="-1">Tester, apprendre, recommencer <a class="header-anchor" href="#tester-apprendre-recommencer" aria-label="Permalink to &quot;Tester, apprendre, recommencer&quot;">​</a></h2><p>Le <strong>user testing</strong> consiste à observer de vrais utilisateurs, pas à leur demander ce qu’ils veulent :</p><ul><li><strong>Avant</strong> : une question à laquelle répondre, 2 à 4 tâches réalistes, les bonnes personnes.</li><li><strong>Pendant</strong> : observer sans aider ; noter hésitations, clics ratés, abandons.</li><li><strong>Après</strong> : synthétiser à plusieurs, corriger, retester.</li></ul><p>C’est une boucle : prototyper → tester → apprendre → nouvelle question. Exemple : le paiement en 1 clic marche… sauf avec une carte d’entreprise. C’est la <strong>continuous discovery</strong> : la discovery ne s’arrête pas au lancement.</p><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><ol><li>Interrogez sur des <strong>faits vécus</strong>, jamais sur des intentions.</li><li>Le PRD tient en <strong>une page</strong> : problème, objectif mesurable, périmètre, critère de succès.</li><li>Prototypez <strong>lo-fi</strong> d’abord, et testez avec de vrais utilisateurs.</li><li>Utilisez l’IA pour aller plus vite vers la preuve, pas pour sauter la preuve.</li></ol><p><strong>Mots-clés</strong> : product discovery, MVP, user interview, experience map, PRD, prototype lo-fi / hi-fi, user testing, continuous discovery — voir le glossaire.</p>',31)])])}const h=t(o,[["render",i]]);export{m as __pageData,h as default};
